import json
n=30
g=[[0]*n for _ in range(n)]
colors=[[3,2,2,3],[2,8,8,2],[3,2,2,3],[2,8,8,2]]
starts=[1,8,15,22]
# Four complete 5x5 framed tiles.
for ti,r0 in enumerate(starts):
    for tj,c0 in enumerate(starts):
        for dr in range(5):
            for dc in range(5):
                g[r0+dr][c0+dc] = 4 if dr in (0,4) or dc in (0,4) else colors[ti][tj]
# Partial next tile's top/left border visible along bottom/right edges.
for c0 in starts:
    for dc in range(5): g[29][c0+dc]=4
for r0 in starts:
    for dr in range(5): g[r0+dr][29]=4
g[29][29]=4
# For each non-default color, join repeated same-color tile centers across only blank separator cells.
def connect_row(tile_row, color):
    cols=[j for j in range(4) if colors[tile_row][j]==color]
    if len(cols)<2:return
    for j in range(min(cols),max(cols)):
        for y in range(starts[tile_row]+1,starts[tile_row]+4):
            for x in range(starts[j]+5,starts[j+1]):
                if g[y][x]==0:g[y][x]=color

def connect_col(tile_col,color):
    rows=[i for i in range(4) if colors[i][tile_col]==color]
    if len(rows)<2:return
    for i in range(min(rows),max(rows)):
        for x in range(starts[tile_col]+1,starts[tile_col]+4):
            for y in range(starts[i]+5,starts[i+1]):
                if g[y][x]==0:g[y][x]=color
for i in range(4):
    for col in set(colors[i]):
        if col!=2:connect_row(i,col)
for j in range(4):
    for col in {colors[i][j] for i in range(4)}:
        if col!=2:connect_col(j,col)
assert len(g)==30 and all(len(r)==30 for r in g)
print(json.dumps({'action':'submit','grid':g},separators=(',',':')))
